__modules["core.db"] = function()
local ttt = require("ttt")
local U = require("core.util")
local S = require("core.state")
local R = require("core.results")
local Sqlite = require("core.sqlite")

-- An open database file: its attached databases (schemas), and per schema the
-- tables and views, loaded on demand. `version` goes up whenever a write may
-- have changed what is in it, so open views know to reload.
local M = {}

local function new_db(path)
  return {
    path = path,
    name = U.basename(path),
    attachments = S.attachments(path),
    schemas = { "main", "temp" },
    files = {},
    schema = "main",
    objects = {},
    info = nil,
    status = "idle",
    err = nil,
    version = 0,
    gen = 0,
  }
end

function M.get(path)
  local db = S.dbs[path]
  if not db then
    db = new_db(path)
    S.dbs[path] = db
  end
  return db
end

function M.open(path)
  local db = M.get(path)
  S.current = db
  S.remember(path)
  if db.status == "idle" or db.status == "error" then
    M.load(db)
  end
  S.redraw()
  return db
end

function M.close(db)
  if S.current == db then
    S.current = nil
  end
  S.dbs[db.path] = nil
  S.redraw()
end

function M.schema_state(db, schema)
  local st = db.objects[schema]
  if not st then
    st = { tables = {}, views = {}, counts = {}, loading = false, loaded = false, err = nil, gen = 0 }
    db.objects[schema] = st
  end
  return st
end

local INFO_SQL = [[
SELECT 'schema' AS k, name, file FROM pragma_database_list ORDER BY seq;
SELECT 'info' AS k, sqlite_version() AS version,
  (SELECT encoding FROM pragma_encoding) AS encoding,
  (SELECT journal_mode FROM pragma_journal_mode) AS journal_mode,
  (SELECT page_size FROM pragma_page_size) AS page_size,
  (SELECT user_version FROM pragma_user_version) AS user_version;]]

local function info_loaded(db, gen, err, sets)
  if gen ~= db.gen then
    return
  end
  local t = R.tagged(sets)
  if not t.info then
    db.status = "error"
    db.err = err or "Could not read the database"
    S.redraw()
    return
  end
  db.status = "ok"
  db.err = err
  db.info = t.info[1]
  local schemas, files = { "main", "temp" }, { main = db.path }
  for _, rec in ipairs(t.schema or {}) do
    if rec.name ~= "main" and rec.name ~= "temp" then
      schemas[#schemas + 1] = rec.name
    end
    files[rec.name] = rec.file
  end
  for _, a in ipairs(db.attachments) do
    if not files[a.alias] then
      schemas[#schemas + 1] = a.alias
    end
  end
  db.schemas = schemas
  db.files = files
  local valid = false
  for _, s in ipairs(schemas) do
    valid = valid or s == db.schema
  end
  if not valid then
    db.schema = "main"
  end
  M.load_objects(db, db.schema)
  S.redraw()
end

-- Reloads what the database holds: its schemas, then the selected schema's
-- tables and views.
function M.load(db)
  db.gen = db.gen + 1
  db.status = "loading"
  db.objects = {}
  Sqlite.run(db, INFO_SQL, {}, U.bind(info_loaded, db, db.gen))
end

local function size_sql(schema)
  local lit = U.literal(schema)
  return "SELECT 'size' AS k, (SELECT page_count FROM pragma_page_count("
    .. lit
    .. ")) * (SELECT page_size FROM pragma_page_size("
    .. lit
    .. ")) AS bytes;"
end

local function objects_sql(schema)
  return "SELECT 'obj' AS k, name, type, sql FROM "
    .. U.ident(schema)
    .. ".sqlite_master WHERE type IN ('table', 'view') AND name NOT LIKE 'sqlite!_%' ESCAPE '!' ORDER BY name;\n"
    .. size_sql(schema)
end

local function counts_loaded(db, st, gen, _, sets)
  if gen ~= st.gen then
    return
  end
  for _, rec in ipairs(R.tagged(sets).count or {}) do
    st.counts[rec.name] = tonumber(rec.n)
  end
  st.counting = false
  S.redraw()
end

local function count_tables(db, schema, st)
  local parts = {}
  for _, t in ipairs(st.tables) do
    if not t.virtual then
      parts[#parts + 1] = "SELECT 'count' AS k, "
        .. U.literal(t.name)
        .. " AS name, count(*) AS n FROM "
        .. U.qualified(schema, t.name)
        .. ";"
    end
  end
  if #parts == 0 then
    return
  end
  st.counting = true
  Sqlite.run(db, table.concat(parts, "\n"), { bail = false }, U.bind(counts_loaded, db, st, st.gen))
end

local function objects_loaded(db, schema, st, gen, err, sets)
  if gen ~= st.gen then
    return
  end
  st.loading = false
  st.loaded = true
  local t = R.tagged(sets)
  if err and not t.obj then
    st.err = err
  end
  st.tables, st.views = {}, {}
  for _, rec in ipairs(t.obj or {}) do
    local item = { name = rec.name, type = rec.type, sql = rec.sql }
    if rec.type == "view" then
      st.views[#st.views + 1] = item
    else
      item.virtual = (rec.sql or ""):upper():find("^%s*CREATE%s+VIRTUAL") ~= nil
      st.tables[#st.tables + 1] = item
    end
  end
  st.bytes = t.size and tonumber(t.size[1].bytes)
  if st.bytes and st.bytes <= (tonumber(S.settings.count_limit_mib) or 0) * 1024 * 1024 then
    count_tables(db, schema, st)
  end
  S.redraw()
end

function M.load_objects(db, schema)
  local st = M.schema_state(db, schema)
  st.gen = st.gen + 1
  st.loading = true
  st.err = nil
  st.counts = {}
  Sqlite.run(db, objects_sql(schema), {}, U.bind(objects_loaded, db, schema, st, st.gen))
  return st
end

function M.ensure_objects(db, schema)
  local st = M.schema_state(db, schema)
  if not st.loaded and not st.loading and db.status == "ok" then
    M.load_objects(db, schema)
  end
  return st
end

function M.select_schema(db, schema)
  db.schema = schema
  M.ensure_objects(db, schema)
  S.redraw()
end

-- After a query that may have written: reload everything that is cached.
function M.changed(db)
  db.version = db.version + 1
  M.load(db)
end

function M.find(db, schema, name)
  local st = db.objects[schema]
  if not st then
    return nil
  end
  for _, list in ipairs({ st.tables, st.views }) do
    for _, item in ipairs(list) do
      if item.name == name then
        return item
      end
    end
  end
end

function M.attach(db, path, alias)
  for _, a in ipairs(db.attachments) do
    if a.alias:lower() == alias:lower() then
      return "A database is already attached as " .. alias
    end
  end
  table.insert(db.attachments, { path = path, alias = alias })
  S.save_attachments(db.path, db.attachments)
  db.schema = alias
  M.load(db)
  ttt.notify("Attached " .. U.basename(path) .. " as " .. alias)
end

function M.detach(db, alias)
  local list = {}
  for _, a in ipairs(db.attachments) do
    if a.alias ~= alias then
      list[#list + 1] = a
    end
  end
  db.attachments = list
  S.save_attachments(db.path, list)
  if db.schema == alias then
    db.schema = "main"
  end
  M.load(db)
  ttt.notify("Detached " .. alias)
end

function M.is_attached(db, schema)
  for _, a in ipairs(db.attachments) do
    if a.alias == schema then
      return true
    end
  end
  return false
end

return M
end

-- src/core/results.lua ------------------------------------------------------
__modules["core.results"] = function()
-- Parses what `sqlite3 -json` prints: one JSON array of flat objects per
-- statement that returned rows, one after another. ttt.json would lose the
-- column order and duplicate column names, and turn large integers into
-- floats, so this reads the objects itself and keeps every value as text.
local M = {}

local function null_text()
  return "NULL"
end

M.NULL = setmetatable({}, { __tostring = null_text })

local function utf8(cp)
  if cp < 0x80 then
    return string.char(cp)
  elseif cp < 0x800 then
    return string.char(0xC0 + math.floor(cp / 0x40), 0x80 + cp % 0x40)
  elseif cp < 0x10000 then
    return string.char(0xE0 + math.floor(cp / 0x1000), 0x80 + math.floor(cp / 0x40) % 0x40, 0x80 + cp % 0x40)
  end
  return string.char(
    0xF0 + math.floor(cp / 0x40000),
    0x80 + math.floor(cp / 0x1000) % 0x40,
    0x80 + math.floor(cp / 0x40) % 0x40,
    0x80 + cp % 0x40
  )
end

local ESCAPES = { b = "\b", f = "\f", n = "\n", r = "\r", t = "\t" }

-- Raised when the text ends inside an item: the item is parsed again once
-- more output has arrived.
local MORE = {}

local function fail(i, what)
  error({ parse = true, message = "unexpected sqlite3 output at byte " .. i .. ": " .. what }, 0)
end

local function short(p, i, what)
  if p.final then
    fail(p.base + i, what or "unexpected end")
  end
  error(MORE, 0)
end

local function byte_at(p, i)
  local b = p.s:byte(i)
  if not b then
    short(p, i)
  end
  return b
end

local function skip(p, i)
  local _, e = p.s:find("^[ \t\r\n,]*", i)
  return e + 1
end

local function read_string(p, i)
  local s = p.s
  local parts = {}
  local start = i + 1
  while true do
    local j = s:find('["\\]', start)
    if not j then
      short(p, i, "unterminated string")
    end
    parts[#parts + 1] = s:sub(start, j - 1)
    if s:byte(j) == 34 then
      return table.concat(parts), j + 1
    end
    local c = s:sub(j + 1, j + 1)
    if c == "" then
      short(p, j)
    elseif c == "u" then
      if j + 5 > #s then
        short(p, j)
      end
      local cp = tonumber(s:sub(j + 2, j + 5), 16) or 63
      local nexti = j + 6
      if cp >= 0xD800 and cp <= 0xDBFF then
        if nexti + 5 > #s then
          short(p, j)
        end
        local lo = s:sub(nexti, nexti + 1) == "\\u" and tonumber(s:sub(nexti + 2, nexti + 5), 16)
        if lo and lo >= 0xDC00 and lo <= 0xDFFF then
          cp = 0x10000 + (cp - 0xD800) * 0x400 + (lo - 0xDC00)
          nexti = nexti + 6
        end
      end
      parts[#parts + 1] = utf8(cp)
      start = nexti
    else
      parts[#parts + 1] = ESCAPES[c] or c
      start = j + 2
    end
  end
end

-- Returns the value as text (or NULL), whether it was a number, and the next
-- position.
local function read_value(p, i)
  local s = p.s
  local b = byte_at(p, i)
  if b == 34 then
    local v, nexti = read_string(p, i)
    return v, false, nexti
  end
  if b == 110 then
    if i + 3 > #s then
      short(p, i)
    end
    if s:sub(i, i + 3) == "null" then
      return M.NULL, false, i + 4
    end
  end
  local _, e = s:find("^[%w%.%+%-]+", i)
  if not e then
    fail(p.base + i, "expected a value")
  end
  if e == #s then
    short(p, i)
  end
  return s:sub(i, e), true, e + 1
end

local function read_object(p, i, set)
  local row, col = {}, 0
  i = skip(p, i + 1)
  while byte_at(p, i) ~= 125 do
    if p.s:byte(i) ~= 34 then
      fail(p.base + i, "expected a column name")
    end
    local name, nexti = read_string(p, i)
    i = skip(p, nexti)
    if byte_at(p, i) ~= 58 then
      fail(p.base + i, "expected ':'")
    end
    i = skip(p, i + 1)
    local value, numeric
    value, numeric, i = read_value(p, i)
    col = col + 1
    if not set.columns[col] then
      set.columns[col] = name
      set.numeric[col] = true
    end
    if value ~= M.NULL and not numeric then
      set.numeric[col] = false
    end
    row[col] = value
    i = skip(p, i)
  end
  return row, i + 1
end

-- sqlite3 -json prints one row per line, and escapes the control characters
-- in strings, so a line ending in "}," or "}]" is exactly one row. Rows past
-- the limit are only counted, which this does without reading their values.
-- Returns the position after the rows it skipped.
local function skip_rows(p, i, set)
  local s = p.s
  while p.set do
    local nl = s:find("\n", i, true)
    if not nl then
      break
    end
    local k = nl - 1
    local b = s:byte(k)
    while b == 32 or b == 13 do
      k = k - 1
      b = s:byte(k)
    end
    if (b ~= 44 and b ~= 93) or s:byte(k - 1) ~= 125 or s:byte(i) ~= 123 then
      break
    end
    set.dropped = set.dropped + 1
    if b == 93 then
      p.set = nil
    end
    i = nl + 1
  end
  return i
end

local function new_set()
  return { columns = {}, numeric = {}, rows = {}, truncated = false, dropped = 0 }
end

-- Parses one item at p.i (a set's "[", a row, a set's "]", or a line of text
-- outside the sets) and returns false at the end of the text.
local function step(p)
  local s, i = p.s, p.i
  local set = p.set
  if not set then
    local _, e = s:find("^%s*", i)
    i = e + 1
    if i > #s then
      p.i = i
      return false
    end
    if s:byte(i) == 91 then
      set = new_set()
      p.set = set
      p.sets[#p.sets + 1] = set
      p.i = i + 1
      return true
    end
    local j = s:find("\n", i, true)
    if not j then
      if not p.final then
        short(p, i)
      end
      j = #s + 1
    end
    p.notes[#p.notes + 1] = s:sub(i, j - 1)
    p.i = j + 1
    return true
  end
  i = skip(p, i)
  local b = byte_at(p, i)
  if b == 93 then
    p.set = nil
    p.i = i + 1
    return true
  end
  if b ~= 123 then
    fail(p.base + i, "expected '{' or ']'")
  end
  if #set.rows >= p.limit then
    set.truncated = true
    local nexti = skip_rows(p, i, set)
    if nexti > i then
      p.i = nexti
      return true
    end
  end
  local row
  row, i = read_object(p, i, set)
  if #set.rows < p.limit then
    set.rows[#set.rows + 1] = row
  else
    set.dropped = set.dropped + 1
  end
  p.i = i
  return true
end

local function run(p)
  while not p.err do
    local i = p.i
    local ok, res = pcall(step, p)
    if not ok then
      p.i = i
      if res ~= MORE then
        p.err = type(res) == "table" and res.message or tostring(res)
      end
      return
    end
    if not res then
      return
    end
  end
end

-- A parser for sqlite3 -json output that arrives in pieces: feed it each
-- chunk, then finish. Rows past limit in a set are counted in dropped and set
-- truncated.
function M.stream(limit)
  return { s = "", i = 1, base = 0, pending = {}, sets = {}, notes = {}, limit = limit or math.huge, final = false }
end

function M.feed(p, chunk)
  if p.err then
    return
  end
  if not chunk:find("\n", 1, true) then
    p.pending[#p.pending + 1] = chunk
    return
  end
  p.pending[#p.pending + 1] = chunk
  p.base = p.base + p.i - 1
  p.s = p.s:sub(p.i) .. table.concat(p.pending)
  p.pending = {}
  p.i = 1
  run(p)
end

-- complete is false when the output was cut short (cancelled, timed out,
-- capped): what is left is an incomplete row and is dropped. Returns sets
-- and notes (lines that were not JSON, from dot-commands), or nil and an
-- error. Each set is { columns, numeric, rows, truncated, dropped }; a row is
-- an array of strings and NULL.
function M.finish(p, complete)
  if complete and not p.err then
    p.base = p.base + p.i - 1
    p.s = p.s:sub(p.i) .. table.concat(p.pending)
    p.pending = {}
    p.i = 1
    p.final = true
    run(p)
    if not p.err and p.set then
      p.err = "unexpected end of sqlite3 output"
    end
  end
  if p.err then
    return nil, p.err
  end
  return p.sets, p.notes
end

-- Rows as tables keyed by column name, for queries the plugin writes itself.
function M.records(set)
  local out = {}
  for r, row in ipairs(set and set.rows or {}) do
    local rec = {}
    for c, name in ipairs(set.columns) do
      local v = row[c]
      if v ~= M.NULL then
        rec[name] = v
      end
    end
    out[r] = rec
  end
  return out
end

-- The records of every set, grouped by their first column, which the
-- plugin's own queries use as a tag: sqlite3 prints nothing for a statement
-- without rows, so position alone cannot say which set is which.
function M.tagged(sets)
  local out = {}
  for _, set in ipairs(sets or {}) do
    for _, rec in ipairs(M.records(set)) do
      local tag = rec[set.columns[1]]
      if tag then
        out[tag] = out[tag] or {}
        table.insert(out[tag], rec)
      end
    end
  end
  return out
end

function M.text(v)
  if v == nil or v == M.NULL then
    return "NULL"
  end
  return v
end

return M
end

