__modules["features.query"] = function()
local U = require("core.util")
local S = require("core.state")
local UI = require("components")
local Router = require("app.router")
local Store = require("features.query.store")

local M = {}

local HINT =
  "Write SQL and press Run or F5. Queries run read-only; one that writes asks first, unless Allow writes is on."

local function sql_input(p, q)
  p:input({
    border = true,
    title = "SQL",
    margin_top = 1,
    multiline = true,
    min_rows = 6,
    max_rows = 12,
    autofocus = true,
    value = q.sql,
    placeholder = "SELECT * FROM sqlite_master;",
    on_change = U.bind(Store.set_sql, q),
  })
end

local function rows_text(q, set)
  local n = #set.rows
  if set.truncated then
    if q.stopped then
      return "first " .. U.count(n) .. " rows shown"
    end
    return "first " .. U.count(n) .. " of " .. U.count(n + set.dropped) .. " rows shown"
  end
  return U.plural(n, "row") .. (q.stopped and " received" or "")
end

local function stats(q)
  if q.running then
    local parts = { U.ms(os.clock() - q.started) }
    if q.received > 0 then
      parts[#parts + 1] = U.plural(q.received, "row") .. " so far"
    end
    return table.concat(parts, " · ")
  end
  if not q.ran then
    return ""
  end
  local parts = {}
  local set = q.sets[q.active]
  if set then
    parts[#parts + 1] = rows_text(q, set)
  elseif not q.stopped and not q.err then
    parts[#parts + 1] = "No rows"
  end
  if q.changes and q.changes > 0 then
    parts[#parts + 1] = U.plural(q.changes, "row") .. " changed"
  end
  parts[#parts + 1] = U.ms(q.elapsed)
  if q.wrote then
    parts[#parts + 1] = "read-write"
  end
  return table.concat(parts, " · ")
end

-- The headline of the last run, when it is not the plain row count.
local function status(q)
  if q.running then
    return "Running…", "muted"
  elseif q.notice then
    return q.notice, "warning"
  elseif q.stopped == "cancelled" then
    return "Cancelled", "warning"
  elseif q.stopped == "timed_out" then
    return "Timed out after " .. U.duration(q.timeout_ms), "danger"
  elseif q.stopped == "truncated" then
    return "Output passed " .. U.bytes(S.OUTPUT_LIMIT) .. ", sqlite3 stopped", "warning"
  elseif q.ran and q.err then
    return "Failed", "danger"
  end
end

local function run(q)
  Store.run(q)
end

local function status_row(q, h)
  local text, style = status(q)
  local detail = stats(q)
  if text then
    h:label({ text = text, style = style, width = U.width(text) })
    detail = detail ~= "" and ("· " .. detail) or ""
  end
  h:label({ text = detail, style = "muted" })
end

local function toolbar(q, h)
  if q.running then
    h:button({ label = "Cancel", on_click = U.bind(Store.cancel, q) })
  else
    h:button({ label = "Run (F5)", on_click = U.bind(run, q) })
  end
  UI.checkbox(h, "Allow writes", q.write, U.bind(Store.set_write, q))
  h:hstack({ height = 1, gap = 1, padding_left = 1, render = U.bind(status_row, q) })
end

local function error_lines(p, q)
  if not q.err then
    return
  end
  for i, line in ipairs(U.lines(q.err)) do
    UI.message(p, line, "danger", { prefix = i == 1 and "✕ " or "  ", margin_top = i == 1 and 1 or nil })
  end
end

local function set_tabs(p, q)
  local items = {}
  for i, set in ipairs(q.sets) do
    items[i] = { id = tostring(i), label = "Result " .. i .. " (" .. #set.rows .. ")" }
  end
  p:tabs({ items = items, active = tostring(q.active), margin_top = 1, on_change = U.bind(Store.select_set, q) })
end

local function page_rows(rows, offset, limit)
  local out = {}
  for i = offset + 1, math.min(offset + limit, #rows) do
    out[#out + 1] = rows[i]
  end
  return out
end

local function grid_box(q, b)
  local set = q.sets[q.active] or { columns = {}, numeric = {}, rows = {} }
  local limit = S.page_size()
  UI.grid(b, q.grid, {
    columns = set.columns,
    numeric = set.numeric,
    rows = page_rows(set.rows, q.offset, limit),
    offset = q.offset,
    limit = limit,
    total = #set.rows,
    on_page = U.bind(Store.set_page, q),
    loading = q.running,
    empty = q.err and "No results" or "The query returned no rows",
    row_title = "Query " .. q.n,
  })
end

local function results(p, q)
  if not q.ran and not q.running and not q.notice then
    p:label({ text = HINT, style = "muted", margin_top = 1, padding_left = 1 })
    return
  end
  for _, note in ipairs(q.notes or {}) do
    p:label({ text = note, style = "muted", padding_left = 1 })
  end
  if #q.sets > 1 then
    set_tabs(p, q)
  end
  UI.frame(p, "Results", U.bind(grid_box, q), { margin_top = #q.sets > 1 and 0 or 1 })
end

local function render(q, p)
  sql_input(p, q)
  p:hstack({ height = 1, gap = 2, margin_top = 1, render = U.bind(toolbar, q) })
  error_lines(p, q)
  results(p, q)
end

local function on_key(q, ev)
  if ev.key == "F5" then
    Store.run(q)
  end
end

local function make_page(q)
  return {
    on_close = U.bind(Store.dispose, q),
    title = "Query " .. q.n,
    trail = { q.db.name },
    tab_title = "Query " .. q.n .. " · " .. q.db.name,
    db_path = q.db.path,
    render = U.bind(render, q),
    on_key = U.bind(on_key, q),
  }
end

function M.open(db, sql)
  if not db then
    return false
  end
  local q = Store.new_query(db, sql)
  Router.show("query:" .. q.n, U.bind(make_page, q))
  return true
end

return M
end

-- src/features/query/store.lua ----------------------------------------------
__modules["features.query.store"] = function()
local ttt = require("ttt")
local U = require("core.util")
local S = require("core.state")
local Sqlite = require("core.sqlite")
local Db = require("core.db")
local UI = require("components")

local M = {}

local MARK = "__ttt_sqlite_changes"

M.count = 0

function M.new_query(db, sql)
  M.count = M.count + 1
  return {
    n = M.count,
    db = db,
    sql = sql or "",
    write = false,
    running = false,
    ran = false,
    err = nil,
    sets = {},
    active = 1,
    offset = 0,
    grid = UI.new_grid(),
    gen = 0,
  }
end

-- sqlite3 prints nothing for statements without rows, so a trailing
-- total_changes() tells a write that changed nothing from one that did.
local function script(sql)
  return sql .. "\n;\nSELECT total_changes() AS " .. MARK .. ";"
end

local function split_changes(sets)
  local last = sets[#sets]
  if last and #last.columns == 1 and last.columns[1] == MARK then
    table.remove(sets)
    return tonumber(last.rows[1] and last.rows[1][1])
  end
  return nil
end

local function stop_ticker(q)
  if q.ticker then
    ttt.clear_interval(q.ticker)
    q.ticker = nil
  end
end

local function received(q, gen, sets)
  if gen ~= q.gen then
    return
  end
  local n = 0
  for _, set in ipairs(sets) do
    if set.columns[1] ~= MARK then
      n = n + #set.rows + set.dropped
    end
  end
  q.received = n
end

local function stop_reason(info)
  if info.cancelled then
    return "cancelled"
  elseif info.timed_out then
    return "timed_out"
  elseif info.truncated then
    return "truncated"
  end
end

local function finished(q, gen, write, err, sets, info)
  if gen ~= q.gen then
    return
  end
  q.running = false
  q.job = nil
  stop_ticker(q)
  local stopped = stop_reason(info)
  if not write and not stopped and Sqlite.refused_write(err) then
    q.err = nil
    q.notice = "Stopped at a statement that writes; nothing was changed."
    S.redraw()
    ttt.confirm("This query writes to " .. q.db.name .. ". Run it again with write access?", U.bind(M.run, q, true))
    return
  end
  q.ran = true
  q.stopped = stopped
  q.timeout_ms = info.timeout_ms
  if stopped then
    q.err = info.stderr ~= "" and info.stderr or nil
  else
    q.err = err
  end
  q.changes = split_changes(sets)
  q.sets = sets
  q.notes = info.notes or {}
  q.elapsed = info.elapsed
  q.wrote = write
  q.active = math.max(#sets, 1)
  q.offset = 0
  q.grid.sel = 1
  if write then
    Db.changed(q.db)
  end
  S.redraw()
end

local function tick(q)
  if q.running then
    S.redraw()
  else
    stop_ticker(q)
  end
end

-- Running again while a run is in flight replaces it: the old sqlite3 is
-- killed and its result, which still arrives, is dropped by the gen check.
function M.run(q, write)
  if U.trim(q.sql) == "" then
    q.err = "Type some SQL first"
    S.redraw()
    return
  end
  Sqlite.cancel(q.job)
  write = write == true or q.write
  q.gen = q.gen + 1
  q.running = true
  q.started = os.clock()
  q.received = 0
  q.err = nil
  q.notice = nil
  stop_ticker(q)
  q.ticker = ttt.set_interval(500, U.bind(tick, q))
  q.job = Sqlite.run(q.db, script(q.sql), {
    write = write,
    limit = tonumber(S.settings.query_row_limit),
    timeout_ms = S.query_timeout_ms(),
    on_progress = U.bind(received, q, q.gen),
  }, U.bind(finished, q, q.gen, write))
  S.redraw()
end

function M.cancel(q)
  Sqlite.cancel(q.job)
end

-- For a closed tab: nothing is left to show the result in.
function M.dispose(q)
  q.gen = q.gen + 1
  stop_ticker(q)
  Sqlite.cancel(q.job)
  q.job = nil
end

function M.set_sql(q, text)
  q.sql = text
end

function M.set_write(q, checked)
  q.write = checked
end

function M.select_set(q, id)
  q.active = tonumber(id) or 1
  q.offset = 0
  q.grid.sel = 1
  S.redraw()
end

function M.set_page(q, offset)
  q.offset = offset
  S.redraw()
end

return M
end

